setup:
const settle=(max)=>{let last=-1,st=0;for(let i=0;i<max;i++){g.renderOnce(1/60);const a=g.lightProbe().adaptation;const e=a?a.autoGain:0;if(i>150&&Math.abs(e-last)<2e-3){if(++st>20)return i;}else st=0;last=e;}return max;};
for (const c of g.rig.circuits.keys()) g.rig.setCircuit(c, true);
g.engine.autoQuality=false;
const r=g.world.goto('stack');
if(g.flashlight){g.flashlight.isOn=false;g.flashlight.on=false;}
const zf=new Set((g.world.zones['stack']||{})._fixtures||[]);
const hb=g.rig.fixtures.filter(f=>f.type==='highbay'&&zf.has(f));
for(const f of hb){
  const sx=Math.sign(f.group.position.x)||1, sz=Math.sign(f.group.position.z)||1;
  if(false) f.target.position.set(-sx*10,-6,-sz*10); else f.target.position.set(0,-3,0);
}
const p=(r&&r.position)||g.world.spawn;
g.look(p[0],p[1],p[2],((r&&r.yaw)||0)+0,0);
const y0=g.player.position.y;
const fr=settle(700);
const pr=g.lightProbe();
console.log('STK2 '+JSON.stringify({aimed:false, yaw:0,
  head:pr.directAtHead, adaptation:pr.adaptation,
  fell:+(y0-g.player.position.y).toFixed(2), authExp:pr.exposure, state:g.state,
  zone:pr.zone, settle:fr, valid:(y0-g.player.position.y)<1 && pr.exposure>0.9 && pr.zone==='stack'}));

